void check(bool ok,const char* what){++count;if(!ok)throw std::runtime_error(what);}
template<class F>bool rejects(F action){try{action();return false;}catch(const std::exception&){return true;}}
int main(){try{
    Esp8266Board board;board.configure("esp32-s3");check(rejects([&]{board.pinMode(46,PinMode::Output);}),"S3 input-only GPIO46");check(rejects([&]{board.pin(26);}),"S3 flash GPIO unavailable");board.setAdcVoltage(1.65);check(board.analogRead()==2048,"12-bit S3 ADC midpoint");board.setAdcVoltage(3.3);check(board.analogRead()==4095,"12-bit ADC full scale");board.configure("esp32");check(rejects([&]{board.pinMode(34,PinMode::InputPullup);}),"ESP32 input-only GPIO34 has no pullup");board.pinMode(16,PinMode::InputPullup);check(board.digitalRead(16)==Level::High,"ESP32 GPIO16 supports pullup");
    CircuitDocument doc;doc.part("board").model="esp32";auto pot=doc.addPart(PartKind::Potentiometer,400,0);doc.connect({pot,"1"},{"board","3V3"});doc.connect({pot,"2"},{"board","GND"});doc.connect({pot,"W"},{"board","A0"});auto state=doc.solve(board);check(state.errors.empty(),"ESP32 potentiometer network");check(std::abs(*state.voltage.at({"board","GPIO36"})-1.65)<1e-8,"pot wiper and ADC alias");doc.part(pot).value=25;check(std::abs(*doc.solve(board).voltage.at({pot,"W"})-2.475)<1e-7,"10k pot at 25 percent from terminal 1");
    CircuitDocument sensors;auto r=sensors.addPart(PartKind::Resistor,0,0);sensors.part(r).value=10000;auto ntc=sensors.addPart(PartKind::Thermistor,0,0);sensors.connect({"board","3V3"},{r,"1"});sensors.connect({r,"2"},{ntc,"1"});sensors.connect({ntc,"2"},{"board","GND"});check(std::abs(*sensors.solve(board).voltage.at({ntc,"1"})-1.65)<1e-7,"NTC 10k at 25 Celsius");sensors.part(ntc).value=85;check(*sensors.solve(board).voltage.at({ntc,"1"})<0.5,"NTC hot resistance falls");sensors.part(ntc).value=-20;check(*sensors.solve(board).voltage.at({ntc,"1"})>2.8,"NTC cold resistance rises");auto light=sensors.addPart(PartKind::Photoresistor,0,0);sensors.part(light).value=10;sensors.connect({light,"1"},{r,"2"});sensors.connect({light,"2"},{"board","GND"});check(*sensors.solve(board).voltage.at({light,"1"})<1.65,"photoresistor loads divider");
    CircuitDocument switches;auto sw=switches.addPart(PartKind::SlideSwitch,0,0);switches.connect({sw,"1"},{"board","GND"});switches.connect({sw,"C"},{"board","GPIO12"});board.pinMode(12,PinMode::InputPullup);check(switches.solve(board).level({"board","GPIO12"})==Level::Low,"SPDT contact 1");switches.part(sw).pressed=true;check(switches.solve(board).level({"board","GPIO12"})==Level::High,"SPDT contact 2 open");for(auto kind:{PartKind::TiltSwitch,PartKind::ReedSwitch}){auto contact=switches.addPart(kind,0,0);switches.connect({contact,"1"},{"board","GPIO12"});switches.connect({contact,"2"},{"board","GND"});switches.part(contact).pressed=true;check(switches.solve(board).level({"board","GPIO12"})==Level::Low,"closed tilt/reed contact");switches.part(contact).pressed=false;}
    CircuitDocument diodes;auto diode=diodes.addPart(PartKind::Diode,0,0),resistor=diodes.addPart(PartKind::Resistor,0,0);diodes.part(resistor).value=1000;diodes.connect({"board","3V3"},{resistor,"1"});diodes.connect({resistor,"2"},{diode,"A"});diodes.connect({diode,"K"},{"board","GND"});state=diodes.solve(board);check(state.errors.empty()&&std::abs(state.ledCurrent.at(diode)-2.6/1001)<1e-9,"silicon diode forward curve");diodes.clearWires();diodes.connect({"board","GND"},{diode,"A"});diodes.connect({"board","3V3"},{diode,"K"});check(diodes.solve(board).ledCurrent.at(diode)==0,"diode reverse blocks");
    CircuitDocument bread;auto bb=bread.addPart(PartKind::Breadboard30,0,0);check(bread.connected({bb,"a1"},{bb,"e1"}),"breadboard five-hole strip");check(!bread.connected({bb,"e1"},{bb,"f1"}),"breadboard center gap isolated");check(!bread.connected({bb,"a1"},{bb,"a2"}),"breadboard adjacent columns isolated");check(bread.connected({bb,"f30"},{bb,"j30"}),"breadboard last column");
    CircuitDocument rgb;auto led=rgb.addPart(PartKind::RGBLed,0,0);rgb.connect({led,"K"},{"board","GND"});for(const auto& channel:{"R","G","B"}){auto limit=rgb.addPart(PartKind::Resistor,0,0);rgb.connect({"board","3V3"},{limit,"1"});rgb.connect({limit,"2"},{led,channel});}state=rgb.solve(board);check(state.errors.empty(),"RGB three independent resistors");check(state.ledCurrent.at(led+":R")>state.ledCurrent.at(led+":G")&&state.ledCurrent.at(led+":G")>state.ledCurrent.at(led+":B"),"RGB distinct forward voltages");
    CircuitDocument seven;auto digit=seven.addPart(PartKind::SevenSegment,0,0),limit=seven.addPart(PartKind::Resistor,0,0);seven.connect({"board","3V3"},{limit,"1"});seven.connect({limit,"2"},{digit,"a"});seven.connect({digit,"COM"},{"board","GND"});state=seven.solve(board);check(state.errors.empty()&&state.ledCurrent.at(digit+":a")>0.005&&state.ledCurrent.at(digit+":b")==0,"7-segment independent segment currents");
    CircuitDocument power;auto battery=power.addPart(PartKind::Battery9V,0,0),meter=power.addPart(PartKind::Voltmeter,0,0);power.connect({battery,"-"},{"board","GND"});power.connect({meter,"-"},{"board","GND"});power.connect({battery,"+"},{meter,"+"});state=power.solve(board);check(state.errors.empty()&&std::abs(*state.voltage.at({meter,"+"})-9)<1e-9,"ideal battery and voltmeter");power.connect({battery,"+"},{"board","GPIO14"});check(!power.solve(board).errors.empty(),"9V GPIO overvoltage rejected");
    board.configure("esp8266");for(const auto& type:componentCatalog()){if(type.kind==PartKind::Esp8266)continue;CircuitDocument empty;empty.addPart(type.kind,0,0);check(empty.solve(board).errors.empty(),"catalog component default is a valid disconnected model");}
    CircuitDocument extras;extras.part("board").model="arduino-uno";board.configure("arduino-uno");
    const auto tmp=extras.addPart(PartKind::TemperatureSensor,0,0);
    check(!extras.solve(board).voltage.at({tmp,"OUT"}),"Unpowered TMP36 output is floating");
    extras.connect({tmp,"VCC"},{"board","5V"});extras.connect({tmp,"GND"},{"board","GND"});
    check(std::abs(*extras.solve(board).voltage.at({tmp,"OUT"})-0.75)<1e-9,"TMP36 outputs 750mV at 25C");
    extras.part(tmp).value=-40;check(std::abs(*extras.solve(board).voltage.at({tmp,"OUT"})-0.1)<1e-9,"TMP36 -40C lower endpoint");
    extras.part(tmp).value=125;check(std::abs(*extras.solve(board).voltage.at({tmp,"OUT"})-1.75)<1e-9,"TMP36 125C upper endpoint");
    extras.clearWires();extras.connect({tmp,"VCC"},{"board","GND"});extras.connect({tmp,"GND"},{"board","5V"});check(!extras.solve(board).errors.empty(),"TMP36 reverse polarity diagnosed");
    extras.clearWires();const auto aa=extras.addPart(PartKind::BatteryAA,0,0);extras.connect({aa,"-"},{"board","GND"});check(std::abs(*extras.solve(board).voltage.at({aa,"+"})-1.5)<1e-9,"AA cell produces 1.5V");
    extras.connect({tmp,"GND"},{"board","GND"});extras.connect({tmp,"VCC"},{aa,"+"});check(!extras.solve(board).voltage.at({tmp,"OUT"}),"TMP36 below minimum supply remains unpowered");
    const auto spst=extras.addPart(PartKind::ToggleSwitch,0,0);check(!extras.connected({spst,"1"},{spst,"2"}),"SPST initially open");extras.part(spst).pressed=true;check(extras.connected({spst,"1"},{spst,"2"}),"SPST closes with state change");
    // Batteries must power a closed circuit without a microcontroller ground.
    for(const auto kind:{PartKind::BatteryAA,PartKind::Battery3V,PartKind::Battery9V,PartKind::PowerSupply}){
        CircuitDocument isolated;isolated.removePart("board");auto cell=isolated.addPart(kind,0,0);auto load=isolated.addPart(PartKind::Resistor,0,0);isolated.part(load).value=1000;
        isolated.connect({cell,"+"},{load,"1"});isolated.connect({cell,"-"},{load,"2"});auto solved=isolated.solve(std::map<std::string,const Esp8266Board*>{});
        check(solved.errors.empty(),"standalone battery/resistor circuit solves");check(std::abs(*solved.voltage.at({load,"1"})-*solved.voltage.at({load,"2"})-isolated.part(cell).value)<1e-8,"battery supplies exact voltage without board GND");
        isolated.connect({cell,"+"},{cell,"-"});check(!isolated.solve(std::map<std::string,const Esp8266Board*>{}).errors.empty(),"shorted ideal battery diagnosed");
    }
    CircuitDocument isolatedLed;auto cell=isolatedLed.addPart(PartKind::Battery9V,0,0),ballast=isolatedLed.addPart(PartKind::Resistor,0,0),lamp=isolatedLed.addPart(PartKind::Led,0,0),contact=isolatedLed.addPart(PartKind::ToggleSwitch,0,0);isolatedLed.part(ballast).value=1000;
    isolatedLed.connect({cell,"+"},{ballast,"1"});isolatedLed.connect({ballast,"2"},{lamp,"A"});isolatedLed.connect({lamp,"K"},{contact,"1"});isolatedLed.connect({contact,"2"},{cell,"-"});
    check(isolatedLed.solve(board).ledCurrent.at(lamp)==0,"open battery circuit remains off");isolatedLed.part(contact).pressed=true;state=isolatedLed.solve(board);check(state.errors.empty()&&std::abs(state.ledCurrent.at(lamp)-7./1010)<1e-8,"battery powers LED through resistor and switch without board GND");
    CircuitDocument series;auto first=series.addPart(PartKind::BatteryAA,0,0),second=series.addPart(PartKind::BatteryAA,0,0),load=series.addPart(PartKind::Resistor,0,0);series.connect({first,"+"},{second,"-"});series.connect({second,"+"},{load,"1"});series.connect({first,"-"},{load,"2"});state=series.solve(board);check(state.errors.empty()&&std::abs(*state.voltage.at({load,"1"})-*state.voltage.at({load,"2"})-3)<1e-8,"two AA cells in series produce 3V");
    CircuitDocument shifted;auto supply=shifted.addPart(PartKind::Battery3V,0,0),upper=shifted.addPart(PartKind::Resistor,0,0),lower=shifted.addPart(PartKind::Resistor,0,0);shifted.part(upper).value=1000;shifted.part(lower).value=1000;shifted.connect({supply,"+"},{upper,"1"});shifted.connect({upper,"2"},{"board","GND"});shifted.connect({supply,"-"},{lower,"1"});shifted.connect({lower,"2"},{"board","GND"});state=shifted.solve(board);check(state.errors.empty()&&std::abs(*state.voltage.at({supply,"+"})-1.5)<1e-8&&std::abs(*state.voltage.at({supply,"-"})+1.5)<1e-8,"floating battery with resistive ground return preserves both terminal potentials");
    CircuitDocument parallel;auto p1=parallel.addPart(PartKind::Battery3V,0,0),p2=parallel.addPart(PartKind::Battery3V,0,0);parallel.connect({p1,"+"},{p2,"+"});parallel.connect({p1,"-"},{p2,"-"});check(parallel.solve(board).errors.empty(),"identical parallel ideal batteries have no redundant matrix constraint");auto conflict=parallel.addPart(PartKind::Battery9V,0,0);parallel.connect({p1,"+"},{conflict,"+"});parallel.connect({p1,"-"},{conflict,"-"});check(!parallel.solve(board).errors.empty(),"unequal parallel batteries rejected");
    std::cout<<count<<" expanded electrical checks passed\n";return 0;
}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
